    fn swap_case(c: str) -> str:
        return c.lower() if c.is_lower() else c.upper()

    var result = ""
    for c in s:
        if c.is_letter():
            result += swap_case(c)
        else:
            result += c
    return result if result.is_letter() else result.reverse()

