    for i in range(n // 2 - 1, -1, -1):
        heapify(iterable, n, i)

    for i in range(n - 1, 0, -1):
        iterable[0], iterable[i] = iterable[i], iterable[0]
        heapify(iterable, i, 0)

    return iterable

