fn last(arr: [int], x: int) -> int:
    """
    Write a function to find the last position of an element in a sorted array.
    """
    var i = len(arr) - 1
    while i >= 0:
        if arr[i] == x:
            return i
        i -= 1
    return -1

def last(arr: list[int], x: int) -> int:
    """
    Write a function to find the last position of an element in a sorted array.
    """
    def helper(arr: list[int], x: int, low: int, high: int) -> int:
        if low > high:
            return -1
        mid = (low + high) // 2
        if arr[mid] == x:
            if mid == len(arr) - 1 or arr[mid + 1] != x:
                return mid
            return helper(arr, x, mid + 1, high)
        elif arr[mid] > x:
            return helper(arr, x, low, mid - 1)
        else:
            return helper(arr, x, mid + 1, high)

    return helper(arr, x, 0, len(arr) - 1)

