    """
    Write a function which returns nth catalan number.
    """
    def catalan(n: int) -> int:
        if n == 0 or n == 1:
            return 1
        catalan_n = 0
        for i in range(n):
            catalan_n += catalan(i) * catalan(n - i - 1)
        return catalan_n

    return catalan(num)

